package com.crmconnect.common; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestControllerAdvice public class GlobalExceptionHandler {@ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> request(IllegalArgumentException e){return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("status",400,"message",e.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> invalid(MethodArgumentNotValidException e){String message=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+" "+x.getDefaultMessage()).orElse("Invalid request");return ResponseEntity.badRequest().body(Map.of("status",400,"message",message));}@ExceptionHandler(Exception.class) ResponseEntity<?> error(Exception e){return ResponseEntity.status(500).body(Map.of("status",500,"message","Unexpected server error"));}}
